#!/usr/bin/env python3
"""build_knowledge_base.py - Structured Chinese legal knowledge base JSON generator.

Produces 6+ JSON data files in backend/data/knowledge_base/ with real Chinese legal
articles organized by category for AI-assisted legal reasoning.
"""

import json
from pathlib import Path
from typing import Any

OUT_DIR = Path(__file__).resolve().parents[1] / "backend" / "data" / "knowledge_base"
OUT_DIR.mkdir(parents=True, exist_ok=True)


def save(name: str, data: list[dict[str, Any]]) -> None:
    """Write a list of article dicts as a UTF-8 JSON file."""
    path = OUT_DIR / name
    path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    print(f"  Wrote {len(data)} articles -> {name}")


# ── 1. 民法基础 ────────────────────────────────────────────────────────

