    return [
        # 格式条款
        {"id":"CC-496","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·合同的订立","article_number":"第四百九十六条","title":"格式条款的定义与提供方义务","content":"格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款，按照对方的要求，对该条款予以说明。提供格式条款的一方未履行提示或者说明义务，致使对方没有注意或者理解与其有重大利害关系的条款的，对方可以主张该条款不成为合同的内容。","applicable_scenarios":["服务协议","消费合同","金融借款","保险合同","电商平台协议","加盟合同"],"keywords":["格式条款","公平原则","提示说明义务","重大利害关系","不成为合同内容","霸王条款"],"judicial_interpretations":["《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条：提供格式条款的一方在合同订立时采用通常足以引起对方注意的文字、符号、字体等明显标识，提示对方注意免除或者减轻其责任、排除或者限制对方权利等与对方有重大利害关系的异常条款的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的提示义务。"],"related_cases":[]},
        {"id":"CC-497","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·合同的订立","article_number":"第四百九十七条","title":"格式条款无效情形","content":"有下列情形之一的，该格式条款无效：（一）具有本法第一编第六章第三节和本法第五百零六条规定的无效情形；（二）提供格式条款一方不合理地免除或者减轻其责任、加重对方责任、限制对方主要权利；（三）提供格式条款一方排除对方主要权利。","applicable_scenarios":["服务协议","消费合同","金融借款","保险合同","电商平台协议","加盟合同"],"keywords":["格式条款无效","免除责任","加重对方责任","限制主要权利","排除主要权利","无效条款"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-498","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·合同的订立","article_number":"第四百九十八条","title":"格式条款解释规则","content":"对格式条款的理解发生争议的，应当按通常理解予以解释。对格式条款有两种以上解释的，应当作出不利于提供格式条款一方的解释。格式条款和非格式条款不一致的，应当采用非格式条款。","applicable_scenarios":["服务协议","消费合同","保险合同","电商平台协议"],"keywords":["格式条款解释","不利解释规则","通常理解","非格式条款优先","合同解释"],"judicial_interpretations":[],"related_cases":[]},
        # 免责条款
        {"id":"CC-506","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·合同的效力","article_number":"第五百零六条","title":"免责条款无效情形","content":"合同中的下列免责条款无效：（一）造成对方人身损害的；（二）因故意或者重大过失造成对方财产损失的。","applicable_scenarios":["服务合同","运输合同","医疗合同","工程合同","保管合同","旅游合同"],"keywords":["免责条款无效","人身损害","故意","重大过失","财产损失","免责声明"],"judicial_interpretations":[],"related_cases":[]},
        # 合同解除
        {"id":"CC-563","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·合同的权利义务终止","article_number":"第五百六十三条","title":"合同法定解除权","content":"有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。以持续履行的债务为内容的不定期合同，当事人可以随时解除合同，但是应当在合理期限之前通知对方。","applicable_scenarios":["各类合同","买卖合同","租赁合同","服务合同","建设工程合同"],"keywords":["合同解除","法定解除权","不可抗力","预期违约","迟延履行","催告","合同目的不能实现"],"judicial_interpretations":[],"related_cases":[]},
        # 违约责任 577-594
        {"id":"CC-577","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百七十七条","title":"违约责任的一般规定","content":"当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。","applicable_scenarios":["各类合同","买卖合同","服务合同","建设工程合同"],"keywords":["违约责任","不履行","履行不符合约定","继续履行","赔偿损失","补救措施"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-578","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百七十八条","title":"预期违约责任","content":"当事人一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满前请求其承担违约责任。","applicable_scenarios":["各类合同","买卖合同","服务合同"],"keywords":["预期违约","明示毁约","默示毁约","履行期限届满前"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-579","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百七十九条","title":"金钱债务的履行请求","content":"当事人一方未支付价款、报酬、租金、利息，或者不履行其他金钱债务的，对方可以请求其支付。","applicable_scenarios":["买卖合同","借款合同","租赁合同","服务合同"],"keywords":["金钱债务","价款","报酬","租金","利息","支付请求"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-580","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十条","title":"非金钱债务违约责任及违约方解除权","content":"当事人一方不履行非金钱债务或者履行非金钱债务不符合约定的，对方可以请求履行，但是有下列情形之一的除外：（一）法律上或者事实上不能履行；（二）债务的标的不适于强制履行或者履行费用过高；（三）债权人在合理期限内未请求履行。有前款规定的除外情形之一，致使不能实现合同目的的，人民法院或者仲裁机构可以根据当事人的请求终止合同权利义务关系，但是不影响违约责任的承担。","applicable_scenarios":["买卖合同","定作合同","服务合同","技术合同"],"keywords":["非金钱债务","不能履行","履行费用过高","强制履行","合同僵局","违约方解除"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-581","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十一条","title":"第三人替代履行","content":"当事人一方不履行债务或者履行债务不符合约定，根据债务的性质不得强制履行的，对方可以请求其负担由第三人替代履行的费用。","applicable_scenarios":["服务合同","定作合同","技术合同"],"keywords":["第三人替代履行","不得强制履行","替代履行费用"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-582","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十二条","title":"质量不符合约定的违约责任","content":"履行不符合约定的，应当按照当事人的约定承担违约责任。对违约责任没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，受损害方根据标的的性质以及损失的大小，可以合理选择请求对方承担修理、重作、更换、退货、减少价款或者报酬等违约责任。","applicable_scenarios":["买卖合同","定作合同","建设工程合同"],"keywords":["质量违约","修理","重作","更换","退货","减少价款","瑕疵履行"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-583","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十三条","title":"赔偿损失与其他违约责任的关系","content":"当事人一方不履行合同义务或者履行合同义务不符合约定的，在履行义务或者采取补救措施后，对方还有其他损失的，应当赔偿损失。","applicable_scenarios":["各类合同"],"keywords":["赔偿损失","继续履行","补救措施","其他损失"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-584","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十四条","title":"损害赔偿的范围与可预见规则","content":"当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约方订立合同时预见到或者应当预见到的因违约可能造成的损失。","applicable_scenarios":["各类合同","买卖合同","服务合同"],"keywords":["损失赔偿范围","可得利益","可预见规则","预期利益","损害赔偿计算"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-585","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十五条","title":"违约金的约定与调整","content":"当事人可以约定一方违约时应当根据违约情况向对方支付一定数额的违约金，也可以约定因违约产生的损失赔偿额的计算方法。约定的违约金低于造成的损失的，人民法院或者仲裁机构可以根据当事人的请求予以增加；约定的违约金过分高于造成的损失的，人民法院或者仲裁机构可以根据当事人的请求予以适当减少。当事人就迟延履行约定违约金的，违约方支付违约金后，还应当履行债务。","applicable_scenarios":["各类合同","买卖合同","建设工程合同","借款合同"],"keywords":["违约金","违约金调整","过分高于","低于损失","迟延履行","惩罚性违约金"],"judicial_interpretations":["《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第六十五条：当事人主张约定的违约金过高请求予以适当减少的，人民法院应当以实际损失为基础，兼顾合同的履行情况、当事人的过错程度以及预期利益等综合因素，根据公平原则和诚实信用原则予以衡量，并作出裁决。当事人约定的违约金超过造成损失的百分之三十的，一般可以认定为过分高于造成的损失。"],"related_cases":[]},
        {"id":"CC-586","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十六条","title":"定金的约定与限额","content":"当事人可以约定一方向对方给付定金作为债权的担保。定金合同自实际交付定金时成立。定金的数额由当事人约定；但是，不得超过主合同标的额的百分之二十，超过部分不产生定金的效力。实际交付的定金数额多于或者少于约定数额的，视为变更约定的定金数额。","applicable_scenarios":["买卖合同","服务合同","建设工程合同"],"keywords":["定金","定金合同","实践合同","定金限额","百分之二十","定金效力"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-587","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十七条","title":"定金罚则","content":"债务人履行债务的，定金应当抵作价款或者收回。给付定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权请求返还定金；收受定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，应当双倍返还定金。","applicable_scenarios":["买卖合同","定作合同","建设工程合同"],"keywords":["定金罚则","双倍返还","无权请求返还","合同目的不能实现"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-588","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百八十八条","title":"违约金与定金的关系","content":"当事人既约定违约金，又约定定金的，一方违约时，对方可以选择适用违约金或者定金条款。定金不足以弥补一方违约造成的损失的，对方可以请求赔偿超过定金数额的损失。","applicable_scenarios":["买卖合同","建设工程合同"],"keywords":["违约金与定金","选择适用","不足以弥补损失"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-590","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百九十条","title":"不可抗力免责","content":"当事人一方因不可抗力不能履行合同的，根据不可抗力的影响，部分或者全部免除责任，但是法律另有规定的除外。因不可抗力不能履行合同的，应当及时通知对方，以减轻可能给对方造成的损失，并应当在合理期限内提供证明。当事人迟延履行后发生不可抗力的，不免除其违约责任。","applicable_scenarios":["各类合同"],"keywords":["不可抗力","免责","通知义务","迟延履行","不可抗力证明"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-591","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百九十一条","title":"减损规则","content":"当事人一方违约后，对方应当采取适当措施防止损失的扩大；没有采取适当措施致使损失扩大的，不得就扩大的损失请求赔偿。当事人因防止损失扩大而支出的合理费用，由违约方负担。","applicable_scenarios":["各类合同"],"keywords":["减损规则","防止损失扩大","合理费用","扩大损失不赔"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-592","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百九十二条","title":"双方违约与过失相抵","content":"当事人都违反合同的，应当各自承担相应的责任。当事人一方违约造成对方损失，对方对损失的发生有过错的，可以减少相应的损失赔偿额。","applicable_scenarios":["各类合同"],"keywords":["双方违约","过失相抵","与有过失","各自承担","减少赔偿额"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-593","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百九十三条","title":"因第三人原因违约的责任","content":"当事人一方因第三人的原因造成违约的，应当依法向对方承担违约责任。当事人一方和第三人之间的纠纷，依照法律规定或者按照约定处理。","applicable_scenarios":["各类合同","买卖合同","运输合同","建设工程合同"],"keywords":["第三人原因","合同相对性","违约责任","追偿"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-594","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·通则·违约责任","article_number":"第五百九十四条","title":"国际贸易合同诉讼时效","content":"因国际货物买卖合同和技术进出口合同争议提起诉讼或者申请仲裁的时效期间为四年。","applicable_scenarios":["国际货物买卖合同","技术进出口合同"],"keywords":["国际货物买卖","技术进出口","诉讼时效","四年"],"judicial_interpretations":[],"related_cases":[]},
        # 借款合同 - 利率
        {"id":"CC-680","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·借款合同","article_number":"第六百八十条","title":"禁止高利放贷与利率确定","content":"禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。","applicable_scenarios":["借款合同","民间借贷","金融借款","P2P借贷"],"keywords":["高利放贷","利率","利息无约定","自然人借款","LPR","市场利率"],"judicial_interpretations":["《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第二十五条：出借人请求借款人按照合同约定利率支付利息的，人民法院应予支持，但是双方约定的利率超过合同成立时一年期贷款市场报价利率四倍的除外。"],"related_cases":[]},
        # 保证合同 681-702
        {"id":"CC-681","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第六百八十一条","title":"保证合同的定义","content":"保证合同是为保障债权的实现，保证人和债权人约定，当债务人不履行到期债务或者发生当事人约定的情形时，保证人履行债务或者承担责任的合同。","applicable_scenarios":["借款合同","融资租赁","建设工程合同","买卖合同"],"keywords":["保证合同","债权保障","保证人","到期债务","担保"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-685","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第六百八十五条","title":"保证合同的书面形式","content":"保证合同可以是单独订立的书面合同，也可以是主债权债务合同中的保证条款。第三人单方以书面形式向债权人作出保证，债权人接收且未提出异议的，保证合同成立。","applicable_scenarios":["借款合同","融资租赁","商业保理"],"keywords":["保证合同书面形式","保证条款","保证函","单方保证"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-686","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第六百八十六条","title":"保证方式的推定规则","content":"保证的方式包括一般保证和连带责任保证。当事人在保证合同中对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。","applicable_scenarios":["借款合同","融资租赁","商业保理"],"keywords":["保证方式","一般保证","连带责任保证","推定规则","约定不明"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-687","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第六百八十七条","title":"一般保证的先诉抗辩权","content":"当事人在保证合同中约定，债务人不能履行债务时，由保证人承担保证责任的，为一般保证。一般保证的保证人在主合同纠纷未经审判或者仲裁，并就债务人财产依法强制执行仍不能履行债务前，有权拒绝向债权人承担保证责任，但是有下列情形之一的除外：（一）债务人下落不明，且无财产可供执行；（二）人民法院已经受理债务人破产案件；（三）债权人有证据证明债务人的财产不足以履行全部债务或者丧失履行债务能力；（四）保证人书面表示放弃本款规定的权利。","applicable_scenarios":["借款合同","融资租赁","商业保理"],"keywords":["一般保证","先诉抗辩权","强制执行","债务人破产","下落不明","放弃抗辩"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-688","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第六百八十八条","title":"连带责任保证","content":"当事人在保证合同中约定保证人和债务人对债务承担连带责任的，为连带责任保证。连带责任保证的债务人不履行到期债务或者发生当事人约定的情形时，债权人可以请求债务人履行债务，也可以请求保证人在其保证范围内承担保证责任。","applicable_scenarios":["借款合同","融资租赁","商业保理"],"keywords":["连带责任保证","连带责任","选择请求","保证范围"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-692","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第六百九十二条","title":"保证期间","content":"保证期间是确定保证人承担保证责任的期间，不发生中止、中断和延长。债权人与保证人可以约定保证期间，但是约定的保证期间早于主债务履行期限或者与主债务履行期限同时届满的，视为没有约定；没有约定或者约定不明确的，保证期间为主债务履行期限届满之日起六个月。债权人与债务人对主债务履行期限没有约定或者约定不明确的，保证期间自债权人请求债务人履行债务的宽限期届满之日起计算。","applicable_scenarios":["借款合同","融资租赁","商业保理"],"keywords":["保证期间","除斥期间","六个月","不中止","约定不明"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CC-700","category":"民法基础","law_name":"中华人民共和国民法典","chapter":"合同编·典型合同·保证合同","article_number":"第七百条","title":"保证人的追偿权","content":"保证人承担保证责任后，除当事人另有约定外，有权在其承担保证责任的范围内向债务人追偿，享有债权人对债务人的权利，但是不得损害债权人的利益。","applicable_scenarios":["借款合同","融资租赁","商业保理"],"keywords":["保证人追偿权","代位权","不得损害债权人利益"],"judicial_interpretations":[],"related_cases":[]},
    ]


