        {"id":"EDS-14","category":"AI运营合规","law_name":"中华人民共和国电子签名法","chapter":"第三章 电子签名与认证","article_number":"第十四条","title":"可靠电子签名效力","content":"可靠的电子签名与手写签名或者盖章具有同等的法律效力。","applicable_scenarios":["电子合同签署","AI生成合同签章","在线服务协议"],"keywords":["电子签名","可靠电子签名","同等效力","手写签名","盖章"],"judicial_interpretations":[],"related_cases":[]},
