# ── 3. 数据安全 ────────────────────────────────────────────────────────

def build_data_security() -> list[dict[str, Any]]:
    return [
        # 个人信息保护法
        {"id":"PIPL-13","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第二章 个人信息处理规则·一般规定","article_number":"第十三条","title":"个人信息处理的法律基础","content":"符合下列情形之一的，个人信息处理者方可处理个人信息：（一）取得个人的同意；（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；（三）为履行法定职责或者法定义务所必需；（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；（七）法律、行政法规规定的其他情形。依照本法其他有关规定，处理个人信息应当取得个人同意，但是有前款第二项至第七项规定情形的，不需取得个人同意。","applicable_scenarios":["用户数据处理","员工信息管理","客户数据收集","AI训练数据"],"keywords":["个人信息处理","同意","合同必需","法定职责","人力资源管理","公开信息"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-14","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第二章 个人信息处理规则·一般规定","article_number":"第十四条","title":"同意的有效条件","content":"基于个人同意处理个人信息的，该同意应当由个人在充分知情的前提下自愿、明确作出。法律、行政法规规定处理个人信息应当取得个人单独同意或者书面同意的，从其规定。个人信息的处理目的、处理方式和处理的个人信息种类发生变更的，应当重新取得个人同意。","applicable_scenarios":["用户协议","隐私政策","AI数据采集"],"keywords":["同意","充分知情","自愿明确","单独同意","书面同意","重新取得同意"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-15","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第二章 个人信息处理规则·一般规定","article_number":"第十五条","title":"撤回同意权","content":"基于个人同意处理个人信息的，个人有权撤回其同意。个人信息处理者应当提供便捷的撤回同意的方式。个人撤回同意，不影响撤回前基于个人同意已进行的个人信息处理活动的效力。","applicable_scenarios":["用户数据管理","隐私设置","AI服务"],"keywords":["撤回同意","便捷方式","撤回不影响既往效力"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-17","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第二章 个人信息处理规则·一般规定","article_number":"第十七条","title":"告知义务","content":"个人信息处理者在处理个人信息前，应当以显著方式、清晰易懂的语言真实、准确、完整地向个人告知下列事项：（一）个人信息处理者的名称或者姓名和联系方式；（二）个人信息的处理目的、处理方式，处理的个人信息种类、保存期限；（三）个人行使本法规定权利的方式和程序；（四）法律、行政法规规定应当告知的其他事项。前款规定事项发生变更的，应当将变更部分告知个人。个人信息处理者通过制定个人信息处理规则的方式告知第一款规定事项的，处理规则应当公开，并且便于查阅和保存。","applicable_scenarios":["隐私政策","用户协议","数据处理协议","AI产品合规"],"keywords":["告知义务","处理目的","处理方式","个人信息种类","保存期限","显著方式"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-28","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第二章 个人信息处理规则·敏感个人信息","article_number":"第二十八条","title":"敏感个人信息的处理规则","content":"敏感个人信息是一旦泄露或者非法使用，容易导致自然人的人格尊严受到侵害或者人身、财产安全受到危害的个人信息，包括生物识别、宗教信仰、特定身份、医疗健康、金融账户、行踪轨迹等信息，以及不满十四周岁未成年人的个人信息。只有在具有特定的目的和充分的必要性，并采取严格保护措施的情形下，个人信息处理者方可处理敏感个人信息。","applicable_scenarios":["AI人脸识别","健康数据","金融数据","未成年人信息"],"keywords":["敏感个人信息","生物识别","医疗健康","金融账户","行踪轨迹","未成年人"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-29","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第二章 个人信息处理规则·敏感个人信息","article_number":"第二十九条","title":"敏感个人信息的单独同意","content":"处理敏感个人信息应当取得个人的单独同意；法律、行政法规规定处理敏感个人信息应当取得书面同意的，从其规定。","applicable_scenarios":["AI人脸识别","健康数据","金融数据"],"keywords":["敏感个人信息","单独同意","书面同意"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-45","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第四章 个人在个人信息处理活动中的权利","article_number":"第四十五条","title":"查阅复制权","content":"个人有权向个人信息处理者查阅、复制其个人信息；有本法第十八条第一款、第三十五条规定情形的除外。个人请求查阅、复制其个人信息的，个人信息处理者应当及时提供。个人请求将个人信息转移至其指定的个人信息处理者，符合国家网信部门规定条件的，个人信息处理者应当提供转移的途径。","applicable_scenarios":["用户数据管理","数据迁移","个人信息导出"],"keywords":["查阅权","复制权","数据可携带权","转移","个人信息"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-47","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第四章 个人在个人信息处理活动中的权利","article_number":"第四十七条","title":"删除请求权","content":"有下列情形之一的，个人信息处理者应当主动删除个人信息；个人信息处理者未删除的，个人有权请求删除：（一）处理目的已实现、无法实现或者为实现处理目的不再必要；（二）个人信息处理者停止提供产品或者服务，或者保存期限已届满；（三）个人撤回同意；（四）个人信息处理者违反法律、行政法规或者违反约定处理个人信息；（五）法律、行政法规规定的其他情形。法律、行政法规规定的保存期限未届满，或者删除个人信息从技术上难以实现的，个人信息处理者应当停止除存储和采取必要的安全保护措施之外的处理。","applicable_scenarios":["用户注销","数据处理协议","隐私合规"],"keywords":["删除权","撤回同意","违反约定","停止处理","保存期限"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"PIPL-66","category":"数据安全","law_name":"中华人民共和国个人信息保护法","chapter":"第七章 法律责任","article_number":"第六十六条","title":"行政处罚","content":"违反本法规定处理个人信息，或者处理个人信息未履行本法规定的个人信息保护义务的，由履行个人信息保护职责的部门责令改正，给予警告，没收违法所得，对违法处理个人信息的应用程序，责令暂停或者终止提供服务；拒不改正的，并处一百万元以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下罚款。有前款规定的违法行为，情节严重的，由省级以上履行个人信息保护职责的部门责令改正，没收违法所得，并处五千万元以下或者上一年度营业额百分之五以下罚款，并可以责令暂停相关业务或者停业整顿、通报有关主管部门吊销相关业务许可或者吊销营业执照；对直接负责的主管人员和其他直接责任人员处十万元以上一百万元以下罚款，并可以决定禁止其在一定期限内担任相关企业的董事、监事、高级管理人员和个人信息保护负责人。","applicable_scenarios":["AI企业合规","数据违规处罚","风险评估"],"keywords":["行政处罚","五千万元","营业额百分之五","停业整顿","吊销","董事禁任"],"judicial_interpretations":[],"related_cases":[]},
        # 数据安全法
        {"id":"DSL-21","category":"数据安全","law_name":"中华人民共和国数据安全法","chapter":"第四章 数据安全保护义务","article_number":"第二十一条","title":"数据分类分级保护","content":"国家建立数据分类分级保护制度，根据数据在经济社会发展中的重要程度，以及一旦遭到篡改、破坏、泄露或者非法获取、非法利用，对国家安全、公共利益或者个人、组织合法权益造成的危害程度，对数据实行分类分级保护。国家数据安全工作协调机制统筹协调有关部门制定重要数据目录，加强对重要数据的保护。各地区、各部门应当按照数据分类分级保护制度，确定本地区、本部门以及相关行业、领域的重要数据具体目录，对列入目录的数据进行重点保护。","applicable_scenarios":["数据治理","数据安全制度","企业数据分类"],"keywords":["数据分类分级","重要数据目录","核心数据","重点保护","国家安全"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"DSL-27","category":"数据安全","law_name":"中华人民共和国数据安全法","chapter":"第四章 数据安全保护义务","article_number":"第二十七条","title":"数据处理者安全义务","content":"开展数据处理活动应当依照法律、法规的规定，建立健全全流程数据安全管理制度，组织开展数据安全教育培训，采取相应的技术措施和其他必要措施，保障数据安全。利用互联网等信息网络开展数据处理活动，应当在网络安全等级保护制度的基础上，履行上述数据安全保护义务。","applicable_scenarios":["企业数据合规","数据安全制度","安全培训"],"keywords":["全流程数据安全管理","安全教育培训","技术措施","等级保护","数据处理"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"DSL-31","category":"数据安全","law_name":"中华人民共和国数据安全法","chapter":"第四章 数据安全保护义务","article_number":"第三十一条","title":"重要数据出境安全评估","content":"关键信息基础设施的运营者在中华人民共和国境内运营中收集和产生的重要数据的出境安全管理，适用《中华人民共和国网络安全法》的规定；其他数据处理者在中华人民共和国境内运营中收集和产生的重要数据的出境安全管理办法，由国家网信部门会同国务院有关部门制定。","applicable_scenarios":["数据出境","跨境数据","跨国企业合规"],"keywords":["重要数据出境","安全评估","关键信息基础设施","跨境数据","网信部门"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"DSL-45","category":"数据安全","law_name":"中华人民共和国数据安全法","chapter":"第六章 法律责任","article_number":"第四十五条","title":"违反数据安全义务的处罚","content":"不履行本法第二十七条、第二十九条、第三十条规定的数据安全保护义务的，由有关主管部门责令改正，给予警告，可以并处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员可以处一万元以上十万元以下罚款；拒不改正或者造成大量数据泄露等严重后果的，处五十万元以上二百万元以下罚款，并可以责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下罚款。","applicable_scenarios":["数据违规处罚","风险评估","合规审计"],"keywords":["数据安全保护义务","罚款","暂停业务","停业整顿","吊销"],"judicial_interpretations":[],"related_cases":[]},
        # 网络安全法
        {"id":"CSL-21","category":"数据安全","law_name":"中华人民共和国网络安全法","chapter":"第三章 网络运行安全·一般规定","article_number":"第二十一条","title":"网络安全等级保护制度","content":"国家实行网络安全等级保护制度。网络运营者应当按照网络安全等级保护制度的要求，履行下列安全保护义务，保障网络免受干扰、破坏或者未经授权的访问，防止网络数据泄露或者被窃取、篡改：（一）制定内部安全管理制度和操作规程，确定网络安全负责人，落实网络安全保护责任；（二）采取防范计算机病毒和网络攻击、网络侵入等危害网络安全行为的技术措施；（三）采取监测、记录网络运行状态、网络安全事件的技术措施，并按照规定留存相关的网络日志不少于六个月；（四）采取数据分类、重要数据备份和加密等措施；（五）法律、行政法规规定的其他义务。","applicable_scenarios":["企业网络安全","AI平台安全","等保合规"],"keywords":["网络安全等级保护","等保","安全审计","日志六个月","数据分类备份加密"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CSL-37","category":"数据安全","law_name":"中华人民共和国网络安全法","chapter":"第三章 网络运行安全·关键信息基础设施","article_number":"第三十七条","title":"个人信息和重要数据境内存储","content":"关键信息基础设施的运营者在中华人民共和国境内运营中收集和产生的个人信息和重要数据应当在境内存储。因业务需要，确需向境外提供的，应当按照国家网信部门会同国务院有关部门制定的办法进行安全评估；法律、行政法规另有规定的，依照其规定。","applicable_scenarios":["数据出境","跨境数据传输","跨国企业合规","云服务合规"],"keywords":["数据本地化","境内存储","出境安全评估","关键信息基础设施","个人信息"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CSL-41","category":"数据安全","law_name":"中华人民共和国网络安全法","chapter":"第四章 网络信息安全","article_number":"第四十一条","title":"个人信息收集的合法正当必要原则","content":"网络运营者收集、使用个人信息，应当遵循合法、正当、必要的原则，公开收集、使用规则，明示收集、使用信息的目的、方式和范围，并经被收集者同意。网络运营者不得收集与其提供的服务无关的个人信息，不得违反法律、行政法规的规定和双方的约定收集、使用个人信息，并应当依照法律、行政法规的规定和与用户的约定，处理其保存的个人信息。","applicable_scenarios":["用户数据收集","隐私政策","AI数据采集","平台合规"],"keywords":["合法正当必要","公开规则","明示目的","用户同意","最小必要","无关信息"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CSL-42","category":"数据安全","law_name":"中华人民共和国网络安全法","chapter":"第四章 网络信息安全","article_number":"第四十二条","title":"个人信息泄露报告义务","content":"网络运营者不得泄露、篡改、毁损其收集的个人信息；未经被收集者同意，不得向他人提供个人信息。但是，经过处理无法识别特定个人且不能复原的除外。网络运营者应当采取技术措施和其他必要措施，确保其收集的个人信息安全，防止信息泄露、毁损、丢失。在发生或者可能发生个人信息泄露、毁损、丢失的情况时，应当立即采取补救措施，按照规定及时告知用户并向有关主管部门报告。","applicable_scenarios":["数据泄露应急","安全事件响应","用户通知"],"keywords":["个人信息泄露","不得泄露篡改毁损","补救措施","用户告知","报告义务","匿名化"],"judicial_interpretations":[],"related_cases":[]},
    ]


