        # 建筑法
        {"id":"CNL-07","category":"行业专项","law_name":"中华人民共和国建筑法","chapter":"第二章 建筑许可·施工许可","article_number":"第七条","title":"建筑工程施工许可","content":"建筑工程开工前，建设单位应当按照国家有关规定向工程所在地县级以上人民政府建设行政主管部门申请领取施工许可证；但是，国务院建设行政主管部门确定的限额以下的小型工程除外。按照国务院规定的权限和程序批准开工报告的建筑工程，不再领取施工许可证。","applicable_scenarios":["建设工程合同审查","工程项目合规","施工许可"],"keywords":["建筑工程","施工许可证","开工报告","建设行政主管部门","限额以下小型工程"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CNL-26","category":"行业专项","law_name":"中华人民共和国建筑法","chapter":"第三章 建筑工程发包与承包·发包","article_number":"第二十六条","title":"承包单位资质要求","content":"承包建筑工程的单位应当持有依法取得的资质证书，并在其资质等级许可的业务范围内承揽工程。禁止建筑施工企业超越本企业资质等级许可的业务范围或者以任何形式用其他建筑施工企业的名义承揽工程。禁止建筑施工企业以任何形式允许其他单位或者个人使用本企业的资质证书、营业执照，以本企业的名义承揽工程。","applicable_scenarios":["工程承包合同审查","资质合规","挂靠风险"],"keywords":["资质证书","资质等级","超越资质","挂靠","借用资质","转包"],"judicial_interpretations":[],"related_cases":[]},
        # 土地管理法
        {"id":"LAL-63","category":"行业专项","law_name":"中华人民共和国土地管理法","chapter":"","article_number":"第六十三条","title":"集体经营性建设用地入市","content":"土地利用总体规划、城乡规划确定为工业、商业等经营性用途，并经依法登记的集体经营性建设用地，土地所有权人可以通过出让、出租等方式交由单位或者个人使用，并应当签订书面合同，载明土地界址、面积、动工期限、使用期限、土地用途、规划条件和双方其他权利义务。前款规定的集体经营性建设用地出让、出租等，应当经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表的同意。","applicable_scenarios":["土地使用权合同","房地产开发","产业园建设"],"keywords":["集体经营性建设用地","入市","出让","出租","三分之二以上","村民会议"],"judicial_interpretations":[],"related_cases":[]},
        # 劳动合同法
        {"id":"LCL-10","category":"行业专项","law_name":"中华人民共和国劳动合同法","chapter":"第二章 劳动合同的订立","article_number":"第十条","title":"书面劳动合同的订立","content":"建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。","applicable_scenarios":["劳动合同审查","AI招聘平台","灵活用工"],"keywords":["书面劳动合同","用工之日起一个月内","劳动关系建立","事实劳动关系"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"LCL-39","category":"行业专项","law_name":"中华人民共和国劳动合同法","chapter":"第四章 劳动合同的解除和终止","article_number":"第三十九条","title":"用人单位单方解除合同","content":"劳动者有下列情形之一的，用人单位可以解除劳动合同：（一）在试用期间被证明不符合录用条件的；（二）严重违反用人单位的规章制度的；（三）严重失职，营私舞弊，给用人单位造成重大损害的；（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；（五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的；（六）被依法追究刑事责任的。","applicable_scenarios":["劳动合同纠纷","解雇合法性审查","用工合规"],"keywords":["过失性辞退","严重违反规章制度","严重失职","营私舞弊","被追究刑事责任"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"LCL-82","category":"行业专项","law_name":"中华人民共和国劳动合同法","chapter":"第七章 法律责任","article_number":"第八十二条","title":"未签订劳动合同的双倍工资","content":"用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。","applicable_scenarios":["劳动合同纠纷","用工合规","AI招聘平台"],"keywords":["未签订劳动合同","双倍工资","超过一个月","无固定期限合同","二倍工资"],"judicial_interpretations":[],"related_cases":[]},
        # 保险法
        {"id":"INL-16","category":"行业专项","law_name":"中华人民共和国保险法","chapter":"第二章 保险合同·一般规定","article_number":"第十六条","title":"如实告知义务","content":"订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。投保人故意或者因重大过失未履行前款规定的如实告知义务，足以影响保险人决定是否同意承保或者提高保险费率的，保险人有权解除合同。前款规定的合同解除权，自保险人知道有解除事由之日起，超过三十日不行使而消灭。自合同成立之日起超过二年的，保险人不得解除合同；发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。投保人故意不履行如实告知义务的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，并不退还保险费。投保人因重大过失未履行如实告知义务，对保险事故的发生有严重影响的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，但应当退还保险费。","applicable_scenarios":["保险合同审查","保险理赔","保险产品合规"],"keywords":["如实告知义务","解除权","三十日","二年不可抗辩","故意","重大过失","退还保险费"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"INL-17","category":"行业专项","law_name":"中华人民共和国保险法","chapter":"第二章 保险合同·一般规定","article_number":"第十七条","title":"保险人的说明义务","content":"订立保险合同，采用保险人提供的格式条款的，保险人向投保人提供的投保单应当附格式条款，保险人应当向投保人说明合同的内容。对保险合同中免除保险人责任的条款，保险人在订立合同时应当在投保单、保险单或者其他保险凭证上作出足以引起投保人注意的提示，并对该条款的内容以书面或者口头形式向投保人作出明确说明；未作提示或者明确说明的，该条款不产生效力。","applicable_scenarios":["保险合同审查","保险理赔","保险产品合规"],"keywords":["格式条款","说明义务","免除保险人责任","提示义务","明确说明","条款不产生效力"],"judicial_interpretations":[],"related_cases":[]},
        # 消费者权益保护法
        {"id":"CPL-25","category":"行业专项","law_name":"中华人民共和国消费者权益保护法","chapter":"第三章 经营者的义务","article_number":"第二十五条","title":"网络购物七日无理由退货","content":"经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：（一）消费者定作的；（二）鲜活易腐的；（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；（四）交付的报纸、期刊。除前款所列商品外，其他根据商品性质并经消费者在购买时确认不宜退货的商品，不适用无理由退货。消费者退货的商品应当完好。经营者应当自收到退回商品之日起七日内返还消费者支付的商品价款。退回商品的运费由消费者承担；经营者和消费者另有约定的，按照约定。","applicable_scenarios":["电商平台协议","消费者合同","在线服务条款"],"keywords":["七日无理由退货","网络购物","消费合同","不宜退货","退货商品完好"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"CPL-55","category":"行业专项","law_name":"中华人民共和国消费者权益保护法","chapter":"第七章 法律责任","article_number":"第五十五条","title":"欺诈的惩罚性赔偿","content":"经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。经营者明知商品或者服务存在缺陷，仍然向消费者提供，造成消费者或者其他受害人死亡或者健康严重损害的，受害人有权要求经营者依照本法第四十九条、第五十一条等法律规定赔偿损失，并有权要求所受损失二倍以下的惩罚性赔偿。","applicable_scenarios":["消费纠纷","产品责任","服务合同"],"keywords":["欺诈行为","惩罚性赔偿","退一赔三","五百元兜底","明知缺陷","二倍以下"],"judicial_interpretations":[],"related_cases":[]},
        # 反不正当竞争法
        {"id":"UCL-02","category":"行业专项","law_name":"中华人民共和国反不正当竞争法","chapter":"第二章 不正当竞争行为","article_number":"第二条","title":"经营原则与不正当竞争定义","content":"经营者在生产经营活动中，应当遵循自愿、平等、公平、诚信的原则，遵守法律和商业道德。本法所称的不正当竞争行为，是指经营者在生产经营活动中，违反本法规定，扰乱市场竞争秩序，损害其他经营者或者消费者的合法权益的行为。本法所称的经营者，是指从事商品生产、经营或者提供服务（以下所称商品包括服务）的自然人、法人和非法人组织。","applicable_scenarios":["市场竞争合规","商业秘密保护","广告合规","不正当竞争诉讼"],"keywords":["自愿平等公平诚信","商业道德","不正当竞争","市场竞争秩序","经营者"],"judicial_interpretations":[],"related_cases":[]},
        {"id":"UCL-09","category":"行业专项","law_name":"中华人民共和国反不正当竞争法","chapter":"第二章 不正当竞争行为","article_number":"第九条","title":"侵犯商业秘密","content":"经营者不得实施下列侵犯商业秘密的行为：（一）以盗窃、贿赂、欺诈、胁迫、电子侵入或者其他不正当手段获取权利人的商业秘密；（二）披露、使用或者允许他人使用以前项手段获取的权利人的商业秘密；（三）违反保密义务或者违反权利人有关保守商业秘密的要求，披露、使用或者允许他人使用其所掌握的商业秘密；（四）教唆、引诱、帮助他人违反保密义务或者违反权利人有关保守商业秘密的要求，获取、披露、使用或者允许他人使用权利人的商业秘密。经营者以外的其他自然人、法人和非法人组织实施前款所列违法行为的，视为侵犯商业秘密。第三人明知或者应知商业秘密权利人的员工、前员工或者其他单位、个人实施本条第一款所列违法行为，仍获取、披露、使用或者允许他人使用该商业秘密的，视为侵犯商业秘密。","applicable_scenarios":["商业秘密保护","员工竞业","技术合作","NDA审查"],"keywords":["商业秘密","盗窃","贿赂","电子侵入","违反保密义务","第三人明知"],"judicial_interpretations":[],"related_cases":[]},
        # 税收征收管理法
        {"id":"TCL-63","category":"行业专项","law_name":"中华人民共和国税收征收管理法","chapter":"","article_number":"第六十三条","title":"偷税的认定与处罚","content":"纳税人伪造、变造、隐匿、擅自销毁帐簿、记帐凭证，或者在帐簿上多列支出或者不列、少列收入，或者经税务机关通知申报而拒不申报或者进行虚假的纳税申报，不缴或者少缴应纳税款的，是偷税。对纳税人偷税的，由税务机关追缴其不缴或者少缴的税款、滞纳金，并处不缴或者少缴的税款百分之五十以上五倍以下的罚款；构成犯罪的，依法追究刑事责任。扣缴义务人采取前款所列手段，不缴或者少缴已扣、已收税款，由税务机关追缴其不缴或者少缴的税款、滞纳金，并处不缴或者少缴的税款百分之五十以上五倍以下的罚款；构成犯罪的，依法追究刑事责任。","applicable_scenarios":["税务合规","合同税务条款","企业财务审计"],"keywords":["偷税","虚假申报","多列支出","少列收入","50%至5倍罚款","滞纳金","刑事责任"],"judicial_interpretations":[],"related_cases":[]},
