# ── MAIN ─────────────────────────────────────────────────────────────────

def main() -> None:
    """Generate all knowledge-base JSON files."""
    print("Building Chinese Legal Knowledge Base ...\n")

    datasets: list[tuple[str, list[dict[str, Any]]]] = [
        ("civil_foundation.json", build_civil_foundation()),
        ("ai_compliance.json", build_ai_compliance()),
        ("data_security.json", build_data_security()),
        ("commercial.json", build_commercial()),
        ("industry_specific.json", build_industry_specific()),
        ("criminal_risk.json", build_criminal_risk()),
        ("foreign_compliance.json", build_foreign_compliance()),
    ]

    for filename, data in datasets:
        save(filename, data)

    total = sum(len(d) for _, d in datasets)
    print(f"\nDone.  Total articles: {total}")

    index: dict[str, int] = {}
    for _, data in datasets:
        for art in data:
            cat = art["category"]
            index[cat] = index.get(cat, 0) + 1
    print("\nCategory breakdown:")
    for cat, count in index.items():
        print(f"  {cat}: {count} articles")


if __name__ == "__main__":
    main()